<script lang="ts">
  import type { Readable } from 'svelte/store';
  import TextNodes from './TextNodes.svelte';
  import AssemblySlot from './AssemblySlot.svelte';
  let { store, controller, overlays, t } = $props<{store:Readable<any>,controller:any,overlays:any,t:any}>();
  let root:HTMLDivElement; let pickerRoot=$state<HTMLDivElement>();
  let open=$derived($store.open),pickerOpen=$derived(!!$store.picker && open);
  $effect(()=>{if(open&&root)return overlays.enter(root,{escape:()=>controller.close('backpack')});});
  $effect(()=>{if(pickerOpen&&pickerRoot)return overlays.enter(pickerRoot,{escape:()=>controller.closePicker()});});
</script>
<div id="modal-backpack" bind:this={root} class:show={open} role="dialog" aria-modal="true" aria-label={t($store.equipmentView?'btn.equipment.title':'btn.backpack.title')} tabindex="-1" data-ui-owner="svelte">
  {#if open}<div class="panel"><div class="bp-head"><h3 class="bp-title" data-ui={$store.equipmentView?'btn.equipment.title':'btn.backpack.title'}>{t($store.equipmentView?'btn.equipment.title':'btn.backpack.title')}</h3><div class="bp-head-right"><span class="bp-carry" id="backpack-carry">{$store.carry}</span><input id="backpack-search" type="search" autocomplete="off" placeholder="搜索物品..." value={$store.search} oninput={e=>controller.search(e.currentTarget.value)} /><button type="button" class="bp-close" id="backpack-panel-close" title={t('backpack.close')} onclick={()=>controller.close('backpack')}>✕</button></div></div>
  <div class="bp-workspace"><aside class="bp-equipment-column" aria-label="穿戴装备">
      <div class="bp-equip-panel"><h4 class="equip-title">{t('equip.title')}</h4><div class="equip-list" id="equip-list">{#each $store.groups as group}<div class="equip-group-title">{group.label}</div>{#each group.slots as slot}
        <div class="equip-row" class:has-item={slot.has} class:selected={slot.selected} role="button" tabindex={slot.has?0:-1} use:controller.tooltip={slot.tooltip} onclick={()=>slot.has&&controller.select(slot.ref)} onkeydown={(e:KeyboardEvent)=>{if(e.key==='Enter'&&e.target===e.currentTarget&&slot.has)controller.select(slot.ref);}}><span class="slot-name">{slot.label}</span><span class="item-name">{slot.name}</span><button type="button" class="btn-unequip" disabled={!slot.has} onclick={e=>{e.stopPropagation();controller.action(slot.ref,'unequip');}}>{t(slot.slot==='water_flask'?'flask.action.unequip':'inv.unequip')}</button></div>
        {#if slot.modules.length}<div class="equip-modules"><div class="equip-modules-title">{t('inv.module.title')}</div><div class="equip-modules-grid">{#each slot.modules as m}<div class="equip-module-slot" class:filled={!!m.owner}><span class="m-label">{m.label}</span>{#if m.owner}<span class="m-name">{m.name}</span>{:else}<span class="m-empty">{t('inv.module.empty')}</span>{/if}<button type="button" class={m.owner?'btn-module-remove':'btn-module-add'} onclick={()=>controller.moduleAction(m)}>{t(m.owner?'inv.module.remove':'inv.module.install')}</button></div>{/each}</div></div>{/if}
      {/each}{/each}</div></div>
</aside>
  <div id="backpack-transfer" class="bp-transfer-surface" use:controller.transferView={$store}></div>
  </div>
  <div class="panel-body"><aside class="bp-tabs" id="backpack-tabs">{#each $store.tabs as tab}<button type="button" class="bp-tab-btn" class:active={$store.container===tab.id} data-container={tab.id} onclick={()=>controller.tab(tab.id)}>{tab.label}</button>{/each}</aside>
    <section class="bp-list"><div class="bp-list-head" id="backpack-list-title">{$store.title}</div><div id="backpack-item-list">{#each $store.rows as row}
      <div class="bp-item-row" class:selected={row.selected} role="button" tabindex="0" use:controller.tooltip={row.tooltip} onclick={()=>controller.select(row.ref)} onkeydown={(e:KeyboardEvent)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();controller.select(row.ref);}}}><div class="bp-item-tier"></div><div class="bp-item-main"><div class="bp-item-name">{row.name}{row.qty}</div><div class="bp-item-sub">{row.desc}</div><div class="bp-item-meta">{row.meta}</div></div></div>
      {:else}<div class="bp-detail-empty">{t('scene.bp.empty')}</div>{/each}</div></section>
    <section class="bp-detail"><button type="button" class="bp-detail-close" aria-label="关闭物品详情" onclick={()=>controller.hideDetail()}>×</button><div id="backpack-detail">{#if $store.detail}{@const d=$store.detail}<div class="bp-detail-title">{d.name}{d.qty}</div><div class="bp-detail-desc">{d.desc}</div>{#if d.attrs}<div class="bp-detail-attrs">{d.attrs}</div>{/if}{#if d.modules.length}<div class="bp-detail-modules"><TextNodes nodes={d.modules}/></div>{/if}{#if d.fields.length}<div class="bp-detail-field-rules"><TextNodes nodes={d.fields}/></div>{/if}
      {#if d.assembly}<div class="bp-detail-assembly"><div class="item-assembly-view" class:is-interactive={d.assembly.interactive}><div class="item-assembly-title"><span>{t('item.assembly.title')}</span><span class={'item-assembly-state '+(d.assembly.complete?'complete':'incomplete')}>{t(d.assembly.complete?'item.assembly.complete':'item.assembly.incomplete')}</span></div>{#each d.assembly.slots as slot}<AssemblySlot {slot} interactive={d.assembly.interactive} {controller} {t}/>{/each}</div></div>{/if}
      <div class="bp-detail-actions">{#if d.partHint}<div class="bp-detail-desc">{d.partHint}</div>{/if}{#each d.actions as action}<button type="button" class="bp-action-btn" class:bp-legacy-transfer={action.command==='drop'||action.command==='pickup'} onclick={()=>controller.action(d.ref,action.command,action.part)}>{action.label}</button>{/each}</div>
      {:else}<div class="bp-detail-empty">{t('scene.bp.no_selection')}</div>{/if}</div>
    </section></div></div>{/if}
</div>
{#if pickerOpen}<div class="module-picker-overlay" bind:this={pickerRoot} role="dialog" aria-modal="true" aria-label={$store.picker.title} tabindex="-1" data-ui-owner="svelte"><div class="module-picker"><div class="module-picker-head"><span>{$store.picker.title}</span><button type="button" class="bp-close" onclick={()=>controller.closePicker()}>✕</button></div>{#each $store.picker.entries as entry}<div class="module-picker-item" role="button" tabindex="0" onclick={()=>controller.install(entry)} onkeydown={(e:KeyboardEvent)=>{if(e.key==='Enter')controller.install(entry);}}><span class="pi-name">{entry.name}</span><span class="pi-desc">{entry.desc}</span></div>{:else}<div class="module-picker-empty">{t('inv.module.picker_none')}</div>{/each}</div></div>{/if}
